    private static SettingsView view(SettingService.AsOfView then) {
        Map<String, List<DatedView>> dated = new LinkedHashMap<>();
        then.dated().forEach((key, recorded) -> dated.put(key, recorded.stream().map(DatedView::of).toList()));
