      <p>
        Terms in force:
        <strong data-testid="setting-terms-current">{{ store.terms() }}</strong> days
      </p>
      @for (g of grades; track g) {
        <p>
          Terms in force for grade {{ g }}:
  protected readonly floor = signal('');
  protected readonly floorTyped = signal(false);
